// Filter for patch-related posts
const items = $input.all();

const patchPosts = items.filter(item => {
  const title = item.json.title || '';
  const content = item.json.content || item.json.contentSnippet || '';
  const combined = (title + ' ' + content).toLowerCase();

  // Look for patch-related keywords
  return combined.includes('patch') || 
         combined.includes('7-0-3') ||
         combined.includes('7.0.3') ||
         combined.includes('release') ||
         combined.includes('update') ||
         combined.includes('version');
});

// Get the latest patch post
const latestPatch = patchPosts.length > 0 ? patchPosts[0] : null;

if (!latestPatch) {
  // No patch posts found, end workflow
  return [];
}

return {
  json: {
    title: latestPatch.json.title,
    link: latestPatch.json.link,
    pubDate: latestPatch.json.pubDate,
    content: latestPatch.json.contentSnippet || latestPatch.json.content,
    guid: latestPatch.json.guid || latestPatch.json.link,
    scrapedAt: new Date().toISOString()
  }
};

// Check if this is a new patch post
const currentGuid = $('Filter Patch Posts').item.json.guid;
const currentTitle = $('Filter Patch Posts').item.json.title;
const currentLink = $('Filter Patch Posts').item.json.link;
const currentPubDate = $('Filter Patch Posts').item.json.pubDate;
const currentContent = $('Filter Patch Posts').item.json.content;

// Get previous state
let previousGuid = '';
const readResult = $('Read Previous State').item;

// Check if we successfully read the file
if (readResult && readResult.binary && readResult.binary.data) {
  // File exists and was read successfully
  const buffer = Buffer.from(readResult.binary.data.data, 'base64');
  previousGuid = buffer.toString('utf8').trim();
  console.log('Previous GUID:', previousGuid);
} else if (readResult && readResult.json && readResult.json.data) {
  // Alternative data format
  previousGuid = readResult.json.data.toString('utf8').trim();
  console.log('Previous GUID (alt format):', previousGuid);
} else {
  console.log('No previous state found (first run)');
}

console.log('Current GUID:', currentGuid);

// Check if guid has changed - only mark as new if GUID is actually different
const isNew = previousGuid === '' || currentGuid !== previousGuid;

console.log('Is New?', isNew);

return {
  json: {
    currentGuid: currentGuid,
    previousGuid: previousGuid,
    isNew: isNew,
    title: currentTitle,
    link: currentLink,
    pubDate: currentPubDate,
    content: currentContent
  }
};

// Prepare state data to save
const currentGuid = $json.currentGuid;

console.log('Saving GUID:', currentGuid);

// Create the binary data properly
const textData = currentGuid;

return {
  json: {
    guid: currentGuid
  },
  binary: {
    data: {
      data: Buffer.from(textData, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'openemr_state.txt'
    }
  }
};

